'use strict';
const router=require('express').Router(),crypto=require('crypto');
router.use((req,res,next)=>{const port=process.env.MUSE_STAGING_PORT||process.env.PORT||'3001',origin=req.get('origin');if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress)||(origin&&!['http://localhost:'+port,'http://127.0.0.1:'+port].includes(origin)))return res.status(403).json({error:'Chỉ dùng trên máy này.'});next()});
router.post('/analyze',async(req,res)=>{try{const b=req.body||{},modes=['concept-person','concept-product','concept-elements','concept-kv','concept-compose'];if(!modes.includes(b.mode))throw Error('Chọn loại concept.');for(const k of ['brief','brand','colors','extras'])if(b[k]!==undefined&&(typeof b[k]!=='string'||b[k].length>6000))throw Error('Thông tin concept quá dài hoặc không hợp lệ.');if(!Array.isArray(b.references)||b.references.length>5)throw Error('Chọn tối đa 5 ảnh.');const refs=b.references.map((r,i)=>({tag:String(r.tag||'').replace(/^@/,''),role:['subject','concept','logo','element'].includes(r.role)?r.role:'concept',index:i+1}));if(b.mode==='concept-person'&&!refs.some(r=>r.role==='subject'))throw Error('Thêm ảnh gốc rõ mặt cho nhân vật.');if(!refs.length&&!String(b.brief||'').trim())throw Error('Thêm ảnh hoặc mô tả ý tưởng.');const tags=refs.map(r=>r.tag),resolved=require('../refManifest').resolveJobRefs('',JSON.stringify(tags),true);if(resolved.missingTags.length||resolved.missingFiles.length)throw Error('Ảnh tham chiếu không còn khả dụng.');const id='concept_'+crypto.randomUUID(),packed=tags.length>4?await require('../spaceSmart').packGuides(id,{guide:{refTags:tags,roleRefs:refs}}):null;
 const instruction='Analyze the attached images directly. Return ONLY a valid JSON object, no Markdown or image generation. Build a detailed production-ready creative brief for '+b.mode+'. Subject images are the single source of identity/product geometry, packaging and brand details. Concept references supply only composition, lighting, material, mood and visual language: do NOT copy their people, product, logo, text or brand. Logo image is an exact brand asset, never redesign it. User branding overrides all reference branding. If source has no visible detail, mark it unknown, do not invent. For concept-elements, produce a 2D render of a 3D-looking element, not a 3D file. For concept-compose combine supplied element images into ONE finished key visual. Preserve every provided element geometry, material and details; arrange them with coherent perspective and lighting, rather than treating them merely as style inspiration. Use these keys: objective,reference_roles,source_lock,reference_analysis (composition,lighting,camera,materials,palette,mood),brand_lock,art_direction,layout,negative_constraints. Make every value specific from actual inputs, max 7500 characters. Reference identifiers are @image1 etc in input order.\nUSER INPUT:'+JSON.stringify({brief:b.brief,brand:b.brand,colors:b.colors,extras:b.extras,references:refs})+(packed?'\nCONTACT SHEET:'+packed.guide.text:'');
 const result=await require('../spaceComponents').aiPrompt(id,{prompt:{text:instruction}},{data:{jsonMode:true,refTags:packed?.guide?.refTags||tags,text:'Write only the requested JSON. Never generate an image.'}});let text=String(result.text||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');let analysis;try{analysis=JSON.parse(text)}catch{throw Error('AI chưa trả JSON hợp lệ. Phân tích lại tham khảo; chưa gửi tạo ảnh.')}if(!analysis||typeof analysis!=='object'||Array.isArray(analysis)||JSON.stringify(analysis).length>14000)throw Error('Brief JSON không hợp lệ hoặc quá dài.');analysis.reference_roles=refs.map(r=>({image:'@image'+r.index,role:r.role}));analysis.brand_lock={...typeof analysis.brand_lock==='object'&&analysis.brand_lock,brand:b.brand||null,requested_colors:b.colors||null,logo_reference:refs.find(r=>r.role==='logo')?'@image'+refs.find(r=>r.role==='logo').index:null,rule:'Preserve supplied source identity/product and exact logo. Never import branding from concept references.'};res.json({analysis,provider:'MUSE',attachedImages:tags.length})
 }catch(e){res.status(400).json({error:e.message})}});module.exports=router;
